\label{lemme terme non-oscillant en g}

The $\ensuremath{1/x^N}$ order in the AE of $\ln\ensuremath{\operatorname{det}_{}\ensuremath{\left[I+V\right]}}$ contains the term



\begin{equation}

\ensuremath{\sum\limits_{\sigma=\pm}^{}}  {\ensuremath{ 
    \mathchoice 
    {\dfrac{1}{N}}
    {\dfrac{1}{N}}
    {\frac{1}{N}}
    {\frac{1}{N}}
}} \ensuremath{\left({\ensuremath{ 
    \mathchoice 
    {\dfrac{ i g'_{\sigma} }{ p'_{\sigma} }}
    {\dfrac{ i g'_{\sigma} }{ p'_{\sigma} }}
    {\frac{ i g'_{\sigma} }{ p'_{\sigma} }}
    {\frac{ i g'_{\sigma} }{ p'_{\sigma} }}
}}\right)}^N  \nu^2_{\sigma}  \; .

\label{expression term non-oscillant en g a la N}
\end{equation}



This is the highest possible power of $g$ that can appear in the non-oscillating part of the $x^{-N}$ order in the AE of $\ln\ensuremath{\operatorname{det}_{}\ensuremath{\left[I+V\right]}}$ \eqref{Asymptotic expansion log Fredholm}.

\label{lemme term oscillant en g a la n}
The $\ensuremath{1/x^{N+2}}$ part of the oscillating corrections with period $\ensuremath{\ensuremath{\mathrm{e}}^{ i \sigma x \ensuremath{\left(p_+-p_-\right)}}}$, $\sigma=\pm$, contains the series



\begin{equation}

\ensuremath{\ensuremath{\mathrm{e}}^{\sigma \ensuremath{\left(g_+-g_-\right)}}} \ensuremath{\sum\limits_{k=0}^{n}} \ensuremath{\left({\ensuremath{ 
    \mathchoice 
    {\dfrac{i g_+' }{p'_+}}
    {\dfrac{i g_+' }{p'_+}}
    {\frac{i g_+' }{p'_+}}
    {\frac{i g_+' }{p'_+}}
}}\right)}^k \ensuremath{\left({\ensuremath{ 
    \mathchoice 
    {\dfrac{i g_-' }{p'_-}}
    {\dfrac{i g_-' }{p'_-}}
    {\frac{i g_-' }{p'_-}}
    {\frac{i g_-' }{p'_-}}
}}\right)}^{n-k}

 \ensuremath{\widetilde{O}}_{n,\, k}\ensuremath{\left[ \sigma \, \nu\right]}  \; .

\label{expression term oscillant ordre n}
\end{equation}



We have introduced the functional



\begin{eqnarray}

\ensuremath{\widetilde{O}}_{n,\, k}\ensuremath{\left[\nu\right]} &=& {\ensuremath{ 
    \mathchoice 
    {\dfrac{  \ensuremath{\left[2q x\right]}^{2\ensuremath{\left(\nu_+ + \nu_-\right)}}  }{ \ensuremath{\left(2q\right)}^2 }}
    {\dfrac{  \ensuremath{\left[2q x\right]}^{2\ensuremath{\left(\nu_+ + \nu_-\right)}}  }{ \ensuremath{\left(2q\right)}^2 }}
    {\frac{  \ensuremath{\left[2q x\right]}^{2\ensuremath{\left(\nu_+ + \nu_-\right)}}  }{ \ensuremath{\left(2q\right)}^2 }}
    {\frac{  \ensuremath{\left[2q x\right]}^{2\ensuremath{\left(\nu_+ + \nu_-\right)}}  }{ \ensuremath{\left(2q\right)}^2 }}
}}

{p'_+}^{2\nu_+-1} {p'_-}^{2 \nu_- -1 }

{\ensuremath{ 
    \mathchoice 
    {\dfrac{ \Gamma\ensuremath{\left(1-\nu_-\right)} \Gamma\ensuremath{\left(1-\nu_+\right)} \kappa^2_{-}}{ \Gamma\ensuremath{\left(\nu_-\right)} \Gamma\ensuremath{\left(\nu_+\right)}  \kappa_+^2 }}
    {\dfrac{ \Gamma\ensuremath{\left(1-\nu_-\right)} \Gamma\ensuremath{\left(1-\nu_+\right)} \kappa^2_{-}}{ \Gamma\ensuremath{\left(\nu_-\right)} \Gamma\ensuremath{\left(\nu_+\right)}  \kappa_+^2 }}
    {\frac{ \Gamma\ensuremath{\left(1-\nu_-\right)} \Gamma\ensuremath{\left(1-\nu_+\right)} \kappa^2_{-}}{ \Gamma\ensuremath{\left(\nu_-\right)} \Gamma\ensuremath{\left(\nu_+\right)}  \kappa_+^2 }}
    {\frac{ \Gamma\ensuremath{\left(1-\nu_-\right)} \Gamma\ensuremath{\left(1-\nu_+\right)} \kappa^2_{-}}{ \Gamma\ensuremath{\left(\nu_-\right)} \Gamma\ensuremath{\left(\nu_+\right)}  \kappa_+^2 }}
}}

{\ensuremath{ 
    \mathchoice 
    {\dfrac{ \ensuremath{\left(2 \nu_+-1\right)}_k \ensuremath{\left(2\nu_{-}-1\right)}_{n-k} }{ k! \ensuremath{\left(n-k\right)}!}}
    {\dfrac{ \ensuremath{\left(2 \nu_+-1\right)}_k \ensuremath{\left(2\nu_{-}-1\right)}_{n-k} }{ k! \ensuremath{\left(n-k\right)}!}}
    {\frac{ \ensuremath{\left(2 \nu_+-1\right)}_k \ensuremath{\left(2\nu_{-}-1\right)}_{n-k} }{ k! \ensuremath{\left(n-k\right)}!}}
    {\frac{ \ensuremath{\left(2 \nu_+-1\right)}_k \ensuremath{\left(2\nu_{-}-1\right)}_{n-k} }{ k! \ensuremath{\left(n-k\right)}!}}
}} \; \; ,  \\


 \ensuremath{\mathrm{with}} \; \; \ln\kappa\ensuremath{\left(\lambda\right)} & =&  \ensuremath{\int\limits_{-q}^{q}} {\ensuremath{ 
    \mathchoice 
    {\dfrac{\nu\ensuremath{\left(\lambda\right)}-\nu\ensuremath{\left(\mu\right)}}{\lambda-\mu}}
    {\dfrac{\nu\ensuremath{\left(\lambda\right)}-\nu\ensuremath{\left(\mu\right)}}{\lambda-\mu}}
    {\frac{\nu\ensuremath{\left(\lambda\right)}-\nu\ensuremath{\left(\mu\right)}}{\lambda-\mu}}
    {\frac{\nu\ensuremath{\left(\lambda\right)}-\nu\ensuremath{\left(\mu\right)}}{\lambda-\mu}}
}} \mathrm{d} \mu \;.

\end{eqnarray}

The highest degree of $g$ in the non-oscillating $x^{-N}$ order of the
asymptotic expansion of $J_n\ensuremath{\left[p,g,F\right]}$ reads



\begin{equation}

{\ensuremath{ 
    \mathchoice 
    {\dfrac{\ensuremath{\left(-1\right)}^{n-1}}{\ensuremath{\left(n-1\right)}!}}
    {\dfrac{\ensuremath{\left(-1\right)}^{n-1}}{\ensuremath{\left(n-1\right)}!}}
    {\frac{\ensuremath{\left(-1\right)}^{n-1}}{\ensuremath{\left(n-1\right)}!}}
    {\frac{\ensuremath{\left(-1\right)}^{n-1}}{\ensuremath{\left(n-1\right)}!}}
}} \ensuremath{\sum\limits_{\sigma=\pm}^{}}  {\ensuremath{ 
    \mathchoice 
    {\dfrac{1}{N}}
    {\dfrac{1}{N}}
    {\frac{1}{N}}
    {\frac{1}{N}}
}} \ensuremath{\left({\ensuremath{ 
    \mathchoice 
    {\dfrac{ i g'_{\sigma} }{ p'_{\sigma} }}
    {\dfrac{ i g'_{\sigma} }{ p'_{\sigma} }}
    {\frac{ i g'_{\sigma} }{ p'_{\sigma} }}
    {\frac{ i g'_{\sigma} }{ p'_{\sigma} }}
}}\right)}^N  \ensuremath{\left(F_{\sigma} \right)}^n {  \ensuremath{\partial_{\gamma}}^n \ensuremath{\left(\nu^2_{0}\right)}  }_{\mid_{\gamma=0} }

\quad \ensuremath{\mathrm{where}}  \quad \nu_0= {\ensuremath{ 
    \mathchoice 
    {\dfrac{i}{2\pi}}
    {\dfrac{i}{2\pi}}
    {\frac{i}{2\pi}}
    {\frac{i}{2\pi}}
}} \ln \ensuremath{\left(1+\gamma\right)} \; .

\end{equation}



Similarly, the highest degree in $g$ present in the $x^{-N-2}$ oscillating part at frequency $\ensuremath{\ensuremath{\mathrm{e}}^{ix \sigma \ensuremath{\left(p_+-p_-\right)} }}$, $\sigma=\pm$,
in the AE of $J_n\ensuremath{\left[p,g,F\right]}$ is given by the series



\begin{equation}

 {\ensuremath{ 
    \mathchoice 
    {\dfrac{ \ensuremath{\left(-1\right)}^{n-1} }{ \ensuremath{\left(n-1\right)}!}}
    {\dfrac{ \ensuremath{\left(-1\right)}^{n-1} }{ \ensuremath{\left(n-1\right)}!}}
    {\frac{ \ensuremath{\left(-1\right)}^{n-1} }{ \ensuremath{\left(n-1\right)}!}}
    {\frac{ \ensuremath{\left(-1\right)}^{n-1} }{ \ensuremath{\left(n-1\right)}!}}
}} \ensuremath{\ensuremath{\mathrm{e}}^{\sigma \ensuremath{\left(g_+-g_-\right)}}} \ensuremath{\sum\limits_{k=0}^{N}} \ensuremath{\left({\ensuremath{ 
    \mathchoice 
    {\dfrac{i g_+' }{p'_+}}
    {\dfrac{i g_+' }{p'_+}}
    {\frac{i g_+' }{p'_+}}
    {\frac{i g_+' }{p'_+}}
}}\right)}^k \ensuremath{\left({\ensuremath{ 
    \mathchoice 
    {\dfrac{i g_-' }{p'_-}}
    {\dfrac{i g_-' }{p'_-}}
    {\frac{i g_-' }{p'_-}}
    {\frac{i g_-' }{p'_-}}
}}\right)}^{N-k}

\ensuremath{\partial_{\gamma}}^n \ensuremath{\widetilde{O}}_{N,\, k}\ensuremath{\left[\sigma \nu\right]}_{\mid_{\gamma=0} }  \; .

\end{equation}

