\begin{equation}

x^{-N}I_n^{ \ensuremath{\left(N;0\right)} }\ensuremath{\left[\ensuremath{\mathcal{F}}_n\right]} =  \ensuremath{\ensuremath{\mathrm{e}}^{x \ensuremath{\mathcal{G}} + \ln x \ensuremath{\mathcal{H}} }} W \ensuremath{\left\{{\ensuremath{ 
