    {\frac{1}{N}}
    {\frac{1}{N}}
}}\ensuremath{\left({\ensuremath{ 
    \mathchoice 
    {\dfrac{i \ensuremath{\mathcal{G}}'\ensuremath{\left(\sigma q\right)}}{p'\ensuremath{\left(\sigma q\right)}}}
    {\dfrac{i \ensuremath{\mathcal{G}}'\ensuremath{\left(\sigma q\right)}}{p'\ensuremath{\left(\sigma q\right)}}}
