}}\right)}^N

\ensuremath{\mathcal{V}}^N\ensuremath{\left(\sigma q\right)} \; +\ensuremath{\mathrm{o}}\ensuremath{\left(1\right)} \;.


\end{equation}



We have introduced shorthand notations for the fully reduced functions



\begin{eqnarray}

\ensuremath{\mathcal{G}}=\ensuremath{\mathcal{G}}_0\ensuremath{\ensuremath{\left(\begin{array}{c}  \cdot \\  \cdot   \end{array} \right)}} = \ensuremath{\mathcal{G}}_1\ensuremath{\ensuremath{\left(\begin{array}{c} z \\ z \end{array} \right)}} \; , \quad \ensuremath{\mathcal{H}}=\ensuremath{\mathcal{H}}_0\ensuremath{\ensuremath{\left(\begin{array}{c}  \cdot \\  \cdot   \end{array} \right)}}   \; ,

\quad \ensuremath{\mathcal{W}}=\ensuremath{\mathcal{W}}_0\ensuremath{\ensuremath{\left(\begin{array}{c}  \cdot \\  \cdot   \end{array} \right)}} \; ,  \\


\quad \ensuremath{\mathcal{V}}\ensuremath{\left(\lambda\right)}=\ensuremath{\mathcal{V}}\ensuremath{\ensuremath{\left( \lambda \left| \begin{array}{c}  \cdot \\  \cdot   \end{array} \right. \right)}}  \; \;\; , \qquad

\quad \ensuremath{\mathcal{G}}'\ensuremath{\left(\lambda\right)}= \ensuremath{\partial_{\epsilon}}\ensuremath{\mathcal{G}}_1\ensuremath{\ensuremath{\left(\begin{array}{c}  \lambda  \\ \lambda+\epsilon \end{array} \right)}} _{\mid_{\epsilon=0}} \; .

\end{eqnarray}

